# gradle.properties — explicit opt-in on AGP 8.1-8.2 (default on AGP 8.3+)
android.experimental.startupProfiles.enable=true

// Generator: mark the startup journey so it feeds the startup profile too.
rule.collect(packageName = "com.example.app", includeInStartupProfile = true) {
    pressHome()
    startActivityAndWait()
}

# Narrow beats broad. Keep only the members reflection actually reads:
-keepclassmembers class com.example.** {
    @com.google.gson.annotations.SerializedName <fields>;
}

# ...instead of the sledgehammer that defeats shrinking for the whole package:
# -keep class com.example.** { *; }

# Retrace an obfuscated crash from the same build's mapping file:
#   retrace -m mapping.txt stacktrace.txt

// Diagnose RenderThread cost: toggle HWUI profile bars or A/B software drawing.
// Developer Options > Profile HWUI rendering > "On screen as bars"
// A long bar on an otherwise-idle main thread = RenderThread/GPU cost.

// Diagnostic only — software rendering is not a shipping strategy.
view.setLayerType(View.LAYER_TYPE_SOFTWARE, null)

val jankStats = JankStats.createAndTrack(window) { frameData ->
    if (frameData.isJank) {
        analytics.record("jank_frame", mapOf(
            "durationMs" to frameData.frameDurationUiNanos / 1_000_000,
            "state" to frameData.states.joinToString { "${it.key}=${it.value}" },
        ))
    }
}

// Tag the journey before the measurement window.
jankStats.performanceMetricsState.addState("screen", "feed")
jankStats.performanceMetricsState.addState("interaction", "scroll")

import androidx.tracing.Trace

fun renderFeedItem(item: FeedItem) {
    Trace.beginSection("renderFeedItem")
    try {
        Trace.beginSection("decodeThumb")
        try { decodeThumbnail(item) } finally { Trace.endSection() }
        bind(item)
    } finally {
        Trace.endSection()
    }
}
// In Perfetto: select the slow frame, then read the nested slices inside
// Choreographer#doFrame on the main thread — the widest is the suspect.

@RunWith(AndroidJUnit4::class)
class StringBenchmark {
    @get:Rule val benchmark = BenchmarkRule()

    @Test
    fun joinVsBuilder() = benchmark.measureRepeated {
        val parts = (0 until 100).map { "part-$it" }
        // consume() defeats dead-code elimination — the result is "used".
        BlackHole.consume(parts.joinToString(","))
    }
}

